import json, glob, os
from collections import defaultdict

vol = defaultdict(lambda: {'node_contexts':0,'props_keys':set(),'edge_targets':set(),'edge_sources':set(),'ref_kinds':set(),'ref_field_used':set()})
for f in glob.glob('*/source-workflow.json'):
    d=json.load(open(f))
    for n in d.get('nodes',[]):
        t=n.get('type'); vol[t]['node_contexts']+=1
        p=n.get('data',{}).get('properties',{})
        vol[t]['props_keys'].update(p.keys())
        for k in ('reference_images','first_frame','input_video','audio'):
            v=n.get('data',{}).get(k)
            if v:
                vol[t]['ref_field_used'].add(k)
                if isinstance(v,list):
                    for it in v:
                        if isinstance(it,dict): vol[t]['ref_kinds'].add(it.get('kind','?'))
                else: vol[t]['ref_kinds'].add(k)
    for e in d.get('edges',[]):
        vol[e.get('targetNodeType','?')]['edge_targets'].add(e.get('targetHandle'))
        # sourceNodeType may be absent; infer from nodes map
for t,v in vol.items():
    print('==== TYPE:',t)
    print('  occurrences:',v['node_contexts'])
    print('  props keys:',sorted(v['props_keys'])[:20])
    print('  edge targetHandles:', sorted(v['edge_targets']))
    print('  ref field used:',sorted(v['ref_field_used']),'kinds:',sorted(v['ref_kinds']))
