LLM 决策时多标一件事：哪些 upload 节点是「使用者输入口」、prompt 里哪段是固定模板。工具落库时生成这份 `app` 清单。web 预览把输入槽渲染成「使用者需要提供：📷 你的照片」。

两个问题确认：

{"function": "async () => {
  const wf = await fetch('/api/workflow?name=web-20260824-173841.json').then(r=>r.json());
  // 找 app 清单：从最近一次 generate 响应结构模拟——直接读 out 的 app 文件不在 api 里，用 LAST 不可得，改为直接渲染预览
  window.renderPreview({ok:true, workflow:wf, name:'web-20260824-173841.json', app:{name:'与绿巨人对战', inputs:[{node_id:'zfcqQvK_iPRb3763_6t0Z',type:'image',label:'用户上传',required:true},{node_id:'k2CBbANnK7RtJIssb2nRJ',type:'audio',label:'粘贴的音频 11',required:true}], locked:{prompt:'上传的照片人物与绿巨人对战…运镜稳定',model:'vidu-Q2',duration:8}}});
  const txt = document.getElementById('preview').innerText;
  return {hasInputs: txt.includes('使用者需要提供')||txt.includes('上传'), snippet: txt.slice(0,400)};
}"}
